{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращает Optional, чтобы явно показать, что пользователь может отсутствовать,
// а не возвращать null (это защищает вызывающий код от NullPointerException).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции пользователей и последовательно фильтруем:
    return users.stream()
        // 1) Ищем пользователя с нужным логином.
        // equalsIgnoreCase — чтобы поиск не зависел от регистра (например, "Admin" == "admin").
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // 2) Оставляем только тех, кто НЕ заблокирован И чей срок действия ещё не истёк.
        // isAfter(Instant.now()) — проверяем, что дата истечения позже текущего момента.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Берём первый подходящий элемент; если таких нет — вернётся пустой Optional.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"// Метод реализует повторные попытки выполнения асинхронного действия
// с экспоненциальной задержкой между ними (exponential backoff).
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем все допустимые попытки.
    // i — номер текущей попытки (начиная с 0), используется для расчёта задержки.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем действие и сразу возвращаем его результат,
            // если оно завершилось успешно.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только сетевые ошибки (HttpRequestException).
            // Остальные исключения пробрасываются наружу без повторных попыток —
            // это осознанное решение: ретраить имеет смысл только для
            // временных сбоев сети, а не для логических ошибок.
            //
            // Условие `when (i < attempts - 1)` гарантирует, что после последней
            // неудачной попытки мы НЕ ждём и НЕ повторяемся, а выходим из цикла
            // и бросаем исключение ниже.

            // Ждём перед следующей попыткой.
            // Задержка растёт экспоненциально: 200мс, 400мс, 800мс, ...
            // Это классический exponential backoff: чем больше попыток уже было,
            // тем дольше пауза, чтобы дать серверу/сети «остыть» и снизить
            // нагрузку при массовых сбоях.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Сюда мы попадаем только в том случае, если все попытки исчерпаны
    // и ни одна не завершилась успехом.
    // Бросаем InvalidOperationException, чтобы явно сообщить вызывающему коду,
    // что действие так и не удалось выполнить.
    // На практике этот код недостижим (unreachable): либо метод вернул значение,
    // либо был брошен HttpRequestException на последней попытке, но компилятор
    // требует явный возврат/брос в конце метода.
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// worker — функция-обработчик, которая работает в отдельной горутине.
//
// Она читает задачи (Job) из канала jobs и отправляет результаты (Result)
// в канал results. Параметр wg используется для того, чтобы главный поток
// мог дождаться завершения всех воркеров перед выходом из программы.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer гарантирует, что счётчик WaitGroup будет уменьшён,
    // даже если внутри произойдёт паника или ранний возврат.
    defer wg.Done()

    // Цикл range по каналу завершается автоматически, когда канал закрыт.
    // Это позволяет воркеру корректно остановиться без дополнительных флагов.
    for j := range jobs {
        // process выполняет фактическую работу над задачей.
        r, err := process(j)
        if err != nil {
            // При ошибке логируем её и переходим к следующей задаче,
            // не прерывая работу всего воркера.
            log.Printf("job %d: %v", j.ID, err)
            continue
        }
        // Отправляем результат в канал результатов.
        // Если канал заполнен, горутина заблокируется до освобождения места.
        results <- r
    }
}
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в хеш-мапу.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=Alice;Age=30"` -> `{"name": "Alice", "age": "30"}`.
///
/// Правила обработки:
/// - Ключ приводится к нижнему регистру и обрезаются пробелы по краям,
///   чтобы сравнение ключей было нечувствительным к регистру и лишним пробелам.
/// - Значение тоже обрезается по краям, но регистр сохраняется как есть —
///   значения могут быть произвольными (например, имена), где регистр важен.
/// - Части без символа `=` (пустые сегменты или просто мусор) отбрасываются,
///   а не вызывают панику — это делает разбор устойчивым к некорректному вводу.
///
/// # Аргументы
/// * `s` — исходная строка для разбора.
///
/// # Возвращаемое значение
/// Хеш-мапа, где ключи — нормализованные ключи, значения — очищенные значения.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Режем строку на сегменты по точке с запятой.
    s.split(';')
        // Оставляем только те сегменты, которые содержат символ '='.
        // split_once возвращает Option: None, если '=' нет, — такой сегмент
        // просто пропускается (filter_map убирает None).
        .filter_map(|p| p.split_once('='))
        // Для каждой найденной пары (ключ, значение):
        //  - ключ приводим к нижнему регистру и обрезаем пробелы,
        //  - значение лишь обрезаем пробелы, сохраняя регистр.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем результат в HashMap.
        // Если один и тот же ключ встречается несколько раз, последний
        // перезапишет предыдущий (стандартное поведение HashMap::insert).
        .collect()
}
"}
